import{_ as r,a0 as s,w as o,s as h,ao as d,I as i,x as a,a1 as t,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"FISH：Linux 的一個智能易用的 Shell | LCTT x X-CMD","titleTemplate":false,"description":"FISH：Linux 的一個智能易用的 Shell | LCTT (201509) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"FISH：Linux 的一個智能易用的 Shell | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"FISH：Linux 的一個智能易用的 Shell | LCTT (201509) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201509/20150906 FISH--A smart and user-friendly command line shell for Linux","title":"FISH：Linux 的一個智能易用的 Shell","tag":"201509","desc":""},"relativePath":"201509/20150906 FISH--A smart and user-friendly command line shell for Linux.md","filePath":"[post].md"}'),u={name:"201509/20150906 FISH--A smart and user-friendly command line shell for Linux.md"};function p(f,e,m,x,b,S){const l=s("Link");return o(),h("div",null,[e[16]||(e[16]=d(`<h1 id="fish-linux-的一個智能易用的-shell" tabindex="-1">FISH：Linux 的一個智能易用的 Shell <a class="header-anchor" href="#fish-linux-的一個智能易用的-shell" aria-label="Permalink to “FISH：Linux 的一個智能易用的 Shell”">​</a></h1><p>FISH（friendly interactive shell）是一個用户友好的命令列 shell，主要是用來進行交互式使用。shell 就是一個用來執行其他程序的程序。</p><h3 id="fish-特性" tabindex="-1">FISH 特性 <a class="header-anchor" href="#fish-特性" aria-label="Permalink to “FISH 特性”">​</a></h3><h4 id="自動建議" tabindex="-1">自動建議 <a class="header-anchor" href="#自動建議" aria-label="Permalink to “自動建議”">​</a></h4><p>fish 會根據你的歷史輸入和補完來提供命令建議，就像一個網絡瀏覽器一樣。注意了，就是Netscape Navigator 4.0!</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/07/Fish-Auto-Suggestion.gif" alt=""></p><h4 id="漂亮的vga-色彩" tabindex="-1">漂亮的VGA 色彩 <a class="header-anchor" href="#漂亮的vga-色彩" aria-label="Permalink to “漂亮的VGA 色彩”">​</a></h4><p>fish 原生支持 term256， 它就是一個終端技術的藝術國度。 你將可以擁有一個難以置信的、256 色的shell 來使用。</p><h4 id="理智的腳本" tabindex="-1">理智的腳本 <a class="header-anchor" href="#理智的腳本" aria-label="Permalink to “理智的腳本”">​</a></h4><p>fish 是完全可以通過腳本控制的，而且它的語法又是那麼的簡單、乾淨，而且一致。你甚至不需要去重寫。</p><h4 id="基於-web-的配置" tabindex="-1">基於 web 的配置 <a class="header-anchor" href="#基於-web-的配置" aria-label="Permalink to “基於 web 的配置”">​</a></h4><p>對於少數能使用圖形計算機的幸運兒， 你們可以在網頁上配置你們自己的色彩方案，以及查看函數、變量和歷史記錄。</p><h4 id="幫助手冊補全" tabindex="-1">幫助手冊補全 <a class="header-anchor" href="#幫助手冊補全" aria-label="Permalink to “幫助手冊補全”">​</a></h4><p>其它的 shell 支持可配置的補全， 但是隻有 fish 可以通過自動轉換你安裝好的 man 手冊來實現補全功能。</p><h4 id="開箱即用" tabindex="-1">開箱即用 <a class="header-anchor" href="#開箱即用" aria-label="Permalink to “開箱即用”">​</a></h4><p>fish 將會通過 tab 補全和語法高亮使你非常愉快的使用shell， 同時不需要太多的學習或者配置。</p><h3 id="在ubuntu-15-04-上安裝fish" tabindex="-1">在ubuntu 15.04 上安裝FISH <a class="header-anchor" href="#在ubuntu-15-04-上安裝fish" aria-label="Permalink to “在ubuntu 15.04 上安裝FISH”">​</a></h3><p>打開終端，運行下列命令：</p><pre><code>sudo apt-add-repository ppa:fish-shell/release-2
sudo apt-get update
sudo apt-get install fish
</code></pre><p>###使用FISH###</p><p>打開終端，運行下列命令來啓動FISH：</p><pre><code>fish
</code></pre><p>歡迎來到 fish，友好的交互式shell，輸入指令 help 來了解怎麼使用fish。</p>`,23)),i("p",null,[e[1]||(e[1]=a("閲讀",-1)),t(l,{href:"http://fishshell.com/docs/current/index.html#introduction"},{default:n(()=>[...e[0]||(e[0]=[a("FISH 文檔",-1)])]),_:1}),e[2]||(e[2]=a(" ，掌握使用方法。",-1))]),e[17]||(e[17]=i("hr",null,null,-1)),i("p",null,[e[4]||(e[4]=a("via: ",-1)),t(l,{href:"http://www.ubuntugeek.com/fish-a-smart-and-user-friendly-command-line-shell-for-linux.html"},{default:n(()=>[...e[3]||(e[3]=[a("http://www.ubuntugeek.com/fish-a-smart-and-user-friendly-command-line-shell-for-linux.html",-1)])]),_:1})]),i("p",null,[e[8]||(e[8]=a("作者：",-1)),t(l,{href:"http://www.ubuntugeek.com/author/ubuntufix"},{default:n(()=>[...e[5]||(e[5]=[a("ruchi",-1)])]),_:1}),e[9]||(e[9]=a(" 譯者：",-1)),t(l,{href:"https://github.com/oska874"},{default:n(()=>[...e[6]||(e[6]=[a("oska874",-1)])]),_:1}),e[10]||(e[10]=a(" 校對：",-1)),t(l,{href:"https://github.com/wxy"},{default:n(()=>[...e[7]||(e[7]=[a("wxy",-1)])]),_:1})]),i("p",null,[e[13]||(e[13]=a("本文由 ",-1)),t(l,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[11]||(e[11]=[a("LCTT",-1)])]),_:1}),e[14]||(e[14]=a(" 原創編譯，",-1)),t(l,{href:"https://linux.cn/"},{default:n(()=>[...e[12]||(e[12]=[a("Linux中國",-1)])]),_:1}),e[15]||(e[15]=a(" 榮譽推出",-1))])])}const F=r(u,[["render",p]]);export{w as __pageData,F as default};
